#include "stdlib/blas/base/zrotg.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/complex/float64/ctor.h"
#include "stdlib/strided/base/stride2offset.h"

/**
* Constructs a Givens plane rotation.
*
* @param a        first input value
* @param b        second input value
* @param Out      output array
* @param strideOut  output stride length
*/
void API_SUFFIX( c_zrotg )( const stdlib_complex128_t a, const stdlib_complex128_t b, double *Out, const CBLAS_INT strideOut ) {
	CBLAS_INT offsetOut = stdlib_strided_stride2offset( 5, strideOut );
	API_SUFFIX( c_zrotg_assign )( a, b, Out, strideOut, offsetOut );
	return;
}
